    TwistSquash::SquashKeyA(REGULUS_KEY_B_D_IceLaneA, REGULUS_KEY_B_D_IceLaneB, REGULUS_KEY_B_D_IceLaneC, REGULUS_KEY_B_D_IceLaneD, &(pWorkSpace->mKeyBoxB[3U][0]));

