    TwistSquash::SquashKeyA(REGULUS_KEY_B_E_IceLaneA, REGULUS_KEY_B_E_IceLaneB, REGULUS_KEY_B_E_IceLaneC, REGULUS_KEY_B_E_IceLaneD, &(pWorkSpace->mKeyBoxB[4U][0]));

